CREATE DATABASE IF NOT EXISTS cineverso CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cineverso;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS movies (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,description TEXT,genre VARCHAR(100),release_year SMALLINT UNSIGNED,age_rating VARCHAR(10) DEFAULT 'L',duration_minutes SMALLINT UNSIGNED,poster_path VARCHAR(255),trailer_url VARCHAR(500),stream_path VARCHAR(500),allow_stream TINYINT(1) NOT NULL DEFAULT 0,featured TINYINT(1) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rooms (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(90) NOT NULL,seat_rows TINYINT UNSIGNED NOT NULL DEFAULT 6,seats_per_row TINYINT UNSIGNED NOT NULL DEFAULT 8,active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS showtimes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,movie_id INT UNSIGNED NOT NULL,room_id INT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,price DECIMAL(10,2) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(movie_id) REFERENCES movies(id),FOREIGN KEY(room_id) REFERENCES rooms(id),INDEX(starts_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,showtime_id BIGINT UNSIGNED NOT NULL,total DECIMAL(10,2) NOT NULL,status ENUM('pending','paid','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(showtime_id) REFERENCES showtimes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,showtime_id BIGINT UNSIGNED NOT NULL,seat_label VARCHAR(8) NOT NULL,status ENUM('reserved','cancelled') NOT NULL DEFAULT 'reserved',FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(showtime_id) REFERENCES showtimes(id),UNIQUE KEY uq_seat_showtime (showtime_id,seat_label)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS favorites (user_id INT UNSIGNED NOT NULL,movie_id INT UNSIGNED NOT NULL,PRIMARY KEY(user_id,movie_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(movie_id) REFERENCES movies(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS streaming_access (user_id INT UNSIGNED NOT NULL,movie_id INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,movie_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(movie_id) REFERENCES movies(id) ON DELETE CASCADE) ENGINE=InnoDB;
